import os,json,hashlib
from pathlib import Path
root=Path(os.environ.get('PIDG_MECHANICS_ROOT','runs/pidg-mechanics-v03'));ap=json.loads((root/'appearance-selection.json').read_text());jp=json.loads((root/'joint-selection.json').read_text());assert ap['completed'] and jp['completed'];joint=jp['best_foreground_psnr']>ap['best_foreground_psnr'];checkpoint='joint-best.pt' if joint else 'appearance-best.pt';(root/'final-selection.json').write_text(json.dumps({'completed':True,'joint':joint,'checkpoint':checkpoint,'checkpoint_sha256':hashlib.sha256((root/checkpoint).read_bytes()).hexdigest(),'criterion':'Highest validation foreground PSNR; test images not accessed in this selection','validation_foreground_psnr':max(ap['best_foreground_psnr'],jp['best_foreground_psnr']),'appearance_validation':ap,'joint_validation':jp},indent=2)+'\n')
